#!/usr/bin/env bash
set -euo pipefail
b=$(mktemp -d)
trap 'rm -rf "$b"' EXIT
bash devcheck/build.sh . devcheck/baseline.c "$b/probe"
"$b/probe" controls
"$b/probe" controls changing
printf 'SPEEX_VARIABLE_BASELINE_OK qualities=1,3,8\n'
"$b/probe"
"$b/probe" controls
"$b/probe" controls changing
printf 'SPEEX_VARIABLE_BASELINE_OK qualities=1,3,8\n'
# Existing upstream NB smoke, supplied with generated small PCM data.
bash devcheck/build.sh . libspeex/testenc.c "$b/testenc"
# Upstream testenc requires a PCM file, generated by the included C program.
cc -std=c99 devcheck/pcm.c -o "$b/pcm"
"$b/pcm" > "$b/input.raw"
"$b/testenc" "$b/input.raw" "$b/output.raw" > "$b/upstream.log" 2>&1
test -s "$b/output.raw"
printf 'SPEEX_UPSTREAM_NB_OK\n'
